const PROJECT_VIEW_TTL_MS = 60_000;

interface Fingerprint {
  size: number;
  mtimeMs: number;
  ctimeMs: number;
  ino: number;
}

interface IndexRecord {
  filePath: string;
  fingerprint: Fingerprint;
  info: SessionInfo | null;
